        q * ((∑ i, p.L i * ↑(p.h i)) / ↑↑p.n + (∑ i, p.σ i * √(p.L i * ↑(p.h i))) ^ 2 / (↑↑p.n ^ 3 * δ ^ 2)))).toNNReal

